export function settingsView(s,questions,icon){
 const detail=settingsDetailView(s,questions,icon);if(detail)return detail;const user=profile();
 const row=(glyph,title,sub,attributes,badge='')=>`<button class="settings-row" ${attributes}><span class="settings-row-icon">${icon(glyph)}</span><span class="settings-row-copy"><strong>${title}</strong>${sub?`<small>${sub}</small>`:''}</span>${badge?'<span class="whatsapp-badge">WhatsApp</span>':''}${icon('chevron')}</button>`;
 return `<div class="settings settings-page"><section class="settings-profile"><img class="settings-avatar" src="${escapeText(user.photo)}" alt="Your profile image" width="76" height="76"><div><h2>Hi, ${escapeText(user.name)}.</h2><p>A little space, just for you.</p><span class="mock-profile-badge">Demo account</span></div><button class="settings-profile-edit" data-settings-detail="account" aria-label="View account">${icon('chevron')}</button></section><section class="settings-membership"><img src="illustration-pack/butterfly.png" alt="" width="76" height="70"><div><h3>Grow in your own time.</h3><p>Explore Bible Scroll Plus.</p><button data-action="membership">View membership ${icon('arrow')}</button></div></section><h3 class="settings-section-title">Account & reading</h3><section class="settings-group">${row('settings','Your account',escapeText(user.name)+' · '+escapeText(user.email),'data-settings-detail="account"')}${row('bookmark','Subscription','Free plan · explore Plus','data-settings-detail="subscription"')}${row('sun','Appearance',s.theme==='dark'?'Dark · switch to light':'Light · switch to dark','data-settings-detail="appearance"')}${row('heart','On your heart',s.topics.length?s.topics.join(' · '):'Choose your reading topics','data-settings-detail="topics"')}<div class="settings-form-row"><span class="settings-row-icon">${icon('book')}</span><label for="routine">Reading pace<select id="routine"><option value="">Choose your pace</option>${questions[5].options.map(v=>`<option ${s.routine===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="settings-form-row"><span class="settings-row-icon">${icon('bell')}</span><label class="switchrow" for="reminder">Daily reminder<input id="reminder" type="checkbox" ${s.reminders?'checked':''}></label></div><p class="settings-inline-note">Reminder preference only; notifications aren’t scheduled in this demo.</p></section><h3 class="settings-section-title">Here for you</h3><section class="settings-group">${row('whatsapp','General contact','Questions, ideas or a little hello','data-settings-detail="contact"',true)}${row('whatsapp','Help & support','Let’s work it out together','data-settings-detail="support"',true)}</section><h3 class="settings-section-title">About & legal</h3><section class="settings-group">${row('info','About Bible Scroll','','data-settings-detail="about"')}${row('shield','Privacy policy','','data-settings-detail="privacy"')}${row('document','Terms of use','','data-settings-detail="terms"')}${row('book','Credits & licenses','','data-settings-detail="licenses"')}</section><footer class="settings-signoff"><img src="illustration-pack/olive.png" alt="" width="46" height="56"><p>Rooted in Scripture. Made for real life.</p><small>Version 1.0 · All account & contact details are mock.</small></footer></div>`;
}

const profileKey='bible-scroll-profile-v1';
let page='',draftPhoto;
const escapeText=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function profile(){try{return {name:'Nate',email:'nate@example.com',bio:'Making a little room for faith, every day.',photo:'assets/quiet-meadow.png',...JSON.parse(localStorage.getItem(profileKey)||'{}')}}catch{return {name:'Nate',email:'nate@example.com',bio:'Making a little room for faith, every day.',photo:'assets/quiet-meadow.png'}}}
export function profileName(){return escapeText(profile().name)}
export function settingsTitle(){return ({account:'Your account',topics:'On your heart',subscription:'Subscription',appearance:'Appearance',contact:'General contact',support:'Help & support',about:'About Bible Scroll',privacy:'Privacy policy',terms:'Terms of use',licenses:'Credits & licenses'})[page]||'Settings'}
export function settingsGoBack(){if(!page)return false;page='';draftPhoto=undefined;return true}
export function resetSettingsPage(){page='';draftPhoto=undefined}
const intro=(asset,title,text)=>`<div class="settings-detail-intro"><img src="illustration-pack/${asset}.png" alt="" width="90" height="90"><h2>${title}</h2><p>${text}</p></div>`;
export function settingsDetailView(s,questions,icon){
 if(!page)return null;
 const p=profile();
 if(page==='account')return `<div class="settings settings-page settings-detail"><form id="settings-account-form"><div class="profile-photo-editor"><img id="profile-photo-preview" src="${escapeText(draftPhoto||p.photo)}" alt="Your profile photo" width="110" height="110"><label class="photo-upload-control" for="profile-photo-input">${icon('camera')} Upload photo</label><input id="profile-photo-input" type="file" accept="image/jpeg,image/png,image/webp" class="sr-only"><button class="textbtn" type="button" data-profile-remove>Remove photo</button><p>JPG, PNG or WebP · up to 10 MB.<br>Stored only in this browser.</p><p id="photo-status" role="status"></p></div><label class="settings-field">Name<input name="name" value="${escapeText(p.name)}" required maxlength="40" autocomplete="off"></label><label class="settings-field">Email<input name="email" type="email" value="${escapeText(p.email)}" required maxlength="120" autocomplete="off"></label><label class="settings-field">A little about you<textarea name="bio" maxlength="180" rows="3">${escapeText(p.bio)}</textarea></label><button class="primary settings-save" type="submit">Save profile</button><p class="settings-form-note">Demo profile. No account is created and nothing is uploaded to a server.</p></form></div>`;
 if(page==='topics')return `<div class="settings settings-page settings-detail">${intro('cosmos','What’s on your heart?','Choose the themes you’d like to make space for. You can change these anytime.')}<form id="settings-topics-form"><fieldset class="settings-topic-options"><legend class="sr-only">Reading topics</legend>${questions[4].options.map(v=>`<label><input type="checkbox" name="topic" value="${v}" ${s.topics.includes(v)?'checked':''}><span>${v}</span>${icon('check')}</label>`).join('')}</fieldset><button class="primary settings-save" type="submit">Save reading preferences</button></form></div>`;
 if(page==='appearance')return `<div class="settings settings-page settings-detail">${intro('sunrise','Set the mood.','Choose the appearance that feels comfortable for your reading.')}<fieldset class="settings-appearance"><legend>Appearance</legend>${['light','dark'].map(v=>`<label><input type="radio" name="settings-theme" value="${v}" ${s.theme===v?'checked':''}><span>${v==='light'?'Light':'Dark'} appearance</span></label>`).join('')}</fieldset><p class="settings-form-note">Your background uses the colors in the gradient editor outside the phone.</p></div>`;
 if(page==='subscription')return `<div class="settings settings-page settings-detail">${intro('butterfly','Your reading, your way.','Enjoy free reading, or explore a little more with Plus.')}<section class="settings-subscription-status"><span>Current plan</span><h3>Free reading</h3><p>No active subscription or scheduled payment.</p><ul><li>Read the sample Scripture library</li><li>Save passages that speak to you</li><li>Keep your daily reading rhythm</li></ul></section><button class="primary settings-save" data-action="membership">Explore Plus plans</button><button class="settings-restart" data-settings-restore>Restore purchases</button><p class="settings-form-note" id="subscription-status" role="status">Mock subscription screen · no charges.</p></div>`;
 if(page==='contact'||page==='support')return `<div class="settings settings-page settings-detail">${intro(page==='support'?'community':'olive',page==='support'?'We’re here for you.':'A little hello goes a long way.',page==='support'?'Tell us what you need a hand with.':'Share a question, an idea or something you’d love to see.')}<div class="settings-contact-card">${icon('whatsapp')}<div><strong>WhatsApp ${page==='support'?'support':'contact'}</strong><span>+1 (202) 555-${page==='support'?'0186':'0148'}</span><small>Mock contact · no live messaging</small></div></div><form id="settings-contact-form"><label class="settings-field">Topic<select name="category"><option>General question</option><option>Reading & passages</option><option>Account & profile</option><option>Subscription & billing</option><option>Feedback & ideas</option></select></label><label class="settings-field">Your message<textarea name="message" rows="5" maxlength="1000" required placeholder="How can we help?"></textarea></label><button class="primary settings-save" type="submit">Preview message</button><p class="settings-form-note" role="status" id="contact-preview-status">Demo only. Your message won’t be sent or stored.</p></form>${page==='support'?'<details class="settings-faq"><summary>How do I change my reading topics?</summary><p>Go back to Settings and choose On your heart. Your saved topics update without restarting onboarding.</p></details><details class="settings-faq"><summary>How do I manage a subscription?</summary><p>This prototype has no active purchases. The Subscription page lets you explore the plan preview.</p></details>':''}</div>`;
 const content={
 about:{asset:'open-book',title:'A little space for the Word.',sub:'Rooted in Scripture. Made for real life.',sections:[['Made for your everyday','Bible Scroll is a reading concept for women: a place to pause, explore a passage and carry something meaningful into your day.'],['Read at your pace','Explore the sample King James Version library, save favorite passages and build a gentle daily reading rhythm.'],['This preview','Version 1.0 · Interactive browser mockup. Accounts, contacts and memberships are illustrative. Passage insights are sample content, not a connected AI service.']]},
 privacy:{asset:'journal',title:'Your space is personal.',sub:'Mock privacy policy · November 2026',sections:[['What stays on this device','Reading preferences, saved passages, your streak and any profile edits are saved in this browser’s local storage. A chosen profile photo is resized and saved locally when you press Save profile.'],['Messages & payments','Contact forms only preview your message. No support message or payment information is transmitted by these mock controls.'],['Your choices','You can replace or remove your profile photo and update your details in Your account. Browser site-data controls can clear local preferences.'],['Before launch','This is placeholder content for design review, not a production privacy policy. Final data practices, provider details and contact information must be supplied before release.']]},
 terms:{asset:'bookmark',title:'A thoughtful beginning.',sub:'Mock terms of use · November 2026',sections:[['The prototype','This interactive demo is provided to explore design and navigation. It does not create an account, purchase or paid agreement.'],['Reading & reflections','Scripture examples use the King James Version. Reflections and sample insights are separate from Scripture and are intended for personal exploration.'],['Membership preview','The demo displays $29.99 per year and $2.99 per week. No payment is processed, trial started or subscription activated.'],['Before launch','These are illustrative terms. Final service terms, purchase conditions and applicable legal notices must be reviewed and supplied before release.']]},
 licenses:{asset:'olive',title:'Made with care.',sub:'The details behind this little space.',sections:[['Scripture','Sample reading content: King James Version. Additional translations are not included in this prototype.'],['Interface icons','Lucide outline icons are used under the ISC license, alongside custom line icons following the same visual style.'],['Illustrations','Original generated photographic illustrations and cloud assets are included in the reusable Bible Scroll illustration pack.'],['Product preview','Bible Scroll · version 1.0. No affiliation with WhatsApp, Apple or any third-party Bible app is implied.']]}
 }[page];
 return `<div class="settings settings-page settings-detail settings-legal">${intro(content.asset,content.title,content.sub)}${content.sections.map(([h,t])=>`<section><h3>${h}</h3><p>${t}</p></section>`).join('')}</div>`;
}
export function bindSettings(root,{getState,persist,render,toast}){
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.settingsDetail){page=b.dataset.settingsDetail;draftPhoto=undefined;render();root.scrollTop=0;window.scrollTo(0,0);return}
 if(b.hasAttribute('data-profile-remove')){draftPhoto='assets/quiet-meadow.png';root.querySelector('#profile-photo-preview').src=draftPhoto;root.querySelector('#photo-status').textContent='Default image selected. Save profile to keep this change.'}
 if(b.hasAttribute('data-settings-restore'))root.querySelector('#subscription-status').textContent='No purchases to restore in this demo. No App Store connection is active.';
 });
 root.addEventListener('change',async e=>{
 if(e.target.name==='settings-theme'){getState().theme=e.target.value;persist();render()}
 if(e.target.id!=='profile-photo-input')return;
 const f=e.target.files?.[0],status=root.querySelector('#photo-status');if(!f)return;
 if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024){status.textContent='Choose a JPG, PNG or WebP smaller than 10 MB.';e.target.value='';return}
 try{const bitmap=await createImageBitmap(f);const canvas=document.createElement('canvas');const side=Math.min(bitmap.width,bitmap.height);canvas.width=canvas.height=320;canvas.getContext('2d').drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,320,320);bitmap.close();draftPhoto=canvas.toDataURL('image/jpeg',.85);const preview=root.querySelector('#profile-photo-preview');if(preview){preview.src=draftPhoto;status.textContent='Photo ready. Save profile to keep it.'}}catch{status.textContent='This image couldn’t be opened. Try another photo.'}
 });
 root.addEventListener('submit',e=>{
 if(!e.target.id.startsWith('settings-'))return;e.preventDefault();const form=e.target;
 if(form.id==='settings-account-form'){const data=new FormData(form),name=String(data.get('name')).trim(),email=String(data.get('email')).trim();if(!name){toast('Enter a name to continue.');return}try{localStorage.setItem(profileKey,JSON.stringify({...profile(),name,email,bio:String(data.get('bio')).trim(),photo:draftPhoto||profile().photo}));page='';draftPhoto=undefined;render();root.scrollTop=0;toast('Profile saved on this device.')}catch{toast('Profile couldn’t be saved. Try a smaller photo.')}}
 if(form.id==='settings-topics-form'){getState().topics=new FormData(form).getAll('topic');persist();page='';render();root.scrollTop=0;toast('Reading preferences saved.')}
 if(form.id==='settings-contact-form'){root.querySelector('#contact-preview-status').textContent='Message preview ready. In the finished app this would open a support conversation. Nothing has been sent or stored.'}
 });
}
